package br.com.cineo;
import android.app.*;import android.widget.*;import org.json.*;import android.view.*;import static br.com.cineo.MainActivity.*;
/** A reply conversation stays beside its root comment, without changing the player. */
class ThreadComments {
 final MainActivity a;Dialog dialog;ThreadComments(MainActivity activity){a=activity;}
 void close(){if(dialog!=null)dialog.dismiss();dialog=null;}
 void open(JSONObject root){close();Dialog d=new Dialog(a);dialog=d;LinearLayout panel=a.col();panel.setBackground(a.bg(BG,18));panel.setPadding(a.dp(18),a.dp(18),a.dp(18),a.dp(18));a.title(panel,"Respostas",21);ScrollView scroll=new ScrollView(a);LinearLayout rows=a.col();scroll.addView(rows);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));EditText entry=a.field(panel,"","Responder a "+root.optString("author_name"),false);entry.setSingleLine(false);entry.setMaxLines(3);CheckBox spoiler=new CheckBox(a);spoiler.setText("Contém spoiler");spoiler.setTextColor(MUTED);panel.addView(spoiler);TextView status=a.text(panel,"",12,MUTED);final int sid=a.activeShow.optInt("id"),eid=a.playingEpisode;Button send=a.button(panel,"Publicar resposta",RED,()->{});send.setOnClickListener(v->{String body=entry.getText().toString().trim();if(body.isEmpty())return;send.setEnabled(false);a.safe(()->a.socialRequest("POST","/shows/"+sid+"/comments",a.obj("episode_id",eid,"parent_id",root.optInt("id"),"body",body,"name",a.displayName(),"spoiler",spoiler.isChecked()),r->{if(!d.isShowing())return;send.setEnabled(true);entry.setText("");spoiler.setChecked(false);status.setText("Resposta publicada");load(root.optInt("id"),rows,0,d);}));a.handler.postDelayed(()->{if(d.isShowing())send.setEnabled(true);},15000);});a.button(panel,"Fechar conversa",CARD,()->d.dismiss());d.setContentView(panel);d.show();d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.getWindow().setGravity(Gravity.BOTTOM);d.getWindow().setLayout(-1,(int)(a.getResources().getDisplayMetrics().heightPixels*.8));d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);load(root.optInt("id"),rows,0,d);}
 void load(int root,LinearLayout list,long before,Dialog d){a.socialRequest("GET","/v7/thread/"+root+(before>0?"?before="+before:""),null,r->{if(!d.isShowing())return;if(before==0){list.removeAllViews();render(list,r.getJSONObject("root"),false);}JSONArray rows=r.getJSONArray("items");if(rows.length()==0&&before==0)a.text(list,"Ainda sem respostas. Comece a conversa.",14,MUTED);for(int i=0;i<rows.length();i++)render(list,rows.getJSONObject(i),true);if(!r.isNull("next")){long next=r.getLong("next");Button more=a.button(list,"Mais respostas",CARD,()->{});more.setOnClickListener(v->{list.removeView(more);load(root,list,next,d);});}});}
 void render(LinearLayout list,JSONObject c,boolean reply){LinearLayout card=a.col();card.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));card.setBackground(a.bg(CARD,10));a.title(card,c.optString("author_name"),14);TextView body=a.text(card,c.optBoolean("spoiler")?"Spoiler · toque para revelar":c.optString("body"),14,c.optBoolean("spoiler")?AMBER:WHITE);if(c.optBoolean("spoiler"))body.setOnClickListener(v->{body.setText(c.optString("body"));body.setTextColor(WHITE);});if(reply)a.button(card,"Ver respostas a esta mensagem",BG,()->open(c));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=a.dp(10);p.leftMargin=reply?a.dp(18):0;list.addView(card,p);}
}
